local Message = require('models/message')

local G = GLOBAL
local SUB = G.SUB


-- Testing the Webhook
AddSimPostInit(function()
    -- -- Multiple messages test
    for i=1, 10 do
        SUB.Webhook:SendMessage(Message("Test číslo "..i, "ikonka"))
    end

    -- Multiple embeds with a message (testing the embed count limit)
    SUB.Webhook:SendMessage(Message("Správa", "ikonka"))
    for i = 1, SUB.CONSTANTS.EMBED_COUNT_LIMIT do
        SUB.Webhook:SendMessage(
            Message(nil, nil, {{description="Emebed #"..i}})
        )
    end

    -- Empty Message
    SUB.Webhook:SendMessage(
        Message()
    )

    -- Too long message
    SUB.Webhook:SendMessage(Message(""))

    -- Two message together are too long so they need to be split
    SUB.Webhook:SendMessage(Message(""))
    SUB.Webhook:SendMessage(Message("iiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiiii"))
end)